package com.gameaggregator.tenantservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="tenant_members",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","user_id"})) public class TenantMember extends BaseEntity { @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="user_id",nullable=false) private UUID userId; @Column(nullable=false,length=30) private String status="ACTIVE"; protected TenantMember(){} public TenantMember(UUID tenantId,UUID userId){this.tenantId=tenantId;this.userId=userId;} public UUID getTenantId(){return tenantId;} public UUID getUserId(){return userId;} public String getStatus(){return status;} }
